.ai-loading-block {
  --ai-gradient-1: #06b6d4;
  --ai-gradient-2: #a855f7;
  --ai-gradient-3: #ec4899;
  --ai-gradient-4: #f59e0b;
  --ai-gradient-speed: 6s;
  z-index: 9999;
  pointer-events: auto;
  background: linear-gradient(
    -45deg,
    var(--ai-gradient-1),
    var(--ai-gradient-2),
    var(--ai-gradient-3),
    var(--ai-gradient-4)
  );
  animation: ai-gradient-move var(--ai-gradient-speed) ease infinite;
  opacity: 0.15;
  background-size: 400% 400%;
  position: absolute;
  inset: 0;
}
@keyframes ai-gradient-move {
  0% {
    background-position: 0;
  }
  50% {
    background-position: 100%;
  }
  to {
    background-position: 0;
  }
}
